{"action":"shell","command":"cd /testbed && PYTHONPATH=src:. python -c "
from cachetools.tagged import TaggedCache

# Test R07: TTL zero is immediately expired
c = TaggedCache(2)
c.put('a', 1, ttl=0)
try:
    c.get('a')
    print('FAIL: ttl=0 should be immediately expired')
except KeyError:
    print('OK: ttl=0 immediately expired')

# Test R07: invalid TTL types
try:
    c.put('b', 1, ttl=-1)
    print('FAIL: negative ttl accepted')
except ValueError:
    print('OK: negative ttl rejected')

try:
    c.put('c', 1, ttl=float('inf'))
    print('FAIL: inf ttl accepted')
except ValueError:
    print('OK: inf ttl rejected')

# Test R07: invalid mode in invalidate_many
try:
    c.invalidate_many(['x'], mode='invalid')
    print('FAIL: invalid mode accepted')
except ValueError:
    print('OK: invalid mode rejected')
""}
